package com.portfolio.employee.error;
import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(NotFoundException.class) ResponseEntity<?> missing(RuntimeException e){return ResponseEntity.status(404).body(Map.of("error",e.getMessage()));} @ExceptionHandler(ConflictException.class) ResponseEntity<?> conflict(RuntimeException e){return ResponseEntity.status(409).body(Map.of("error",e.getMessage()));} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> invalid(MethodArgumentNotValidException e){var errors=new LinkedHashMap<String,String>(); e.getBindingResult().getFieldErrors().forEach(x->errors.putIfAbsent(x.getField(),x.getDefaultMessage())); return ResponseEntity.badRequest().body(Map.of("error","Validation failed","fields",errors));} }